142→    cleanupTestFiles();
143→    if (alice || bob || charlie) {
144→      await closeTestAccounts([alice, bob, charlie].filter(Boolean));
145→    }
146→  });
147→
148→  // ============================================
149→  // Phase 1: Account Setup
150→  // ============================================
151→
152→  test('1.1 Create test accounts (Alice, Bob, Charlie)', async () => {
153→    // Create accounts sequentially (each needs its own context + vault init)
154→    alice = await createTestAccount(browser, 'alice', runId);
155→    bob = await createTestAccount(browser, 'bob', runId);
156→    charlie = await createTestAccount(browser, 'charlie', runId);
157→
158→    // Initialize page objects for Alice
159→    aliceFileList = new FileListPage(alice.page);
160→    aliceUploadZone = new UploadZonePage(alice.page);
161→    aliceContextMenu = new ContextMenuPage(alice.page);
162→    aliceCreateFolderDialog = new CreateFolderDialogPage(alice.page);
163→    aliceShareDialog = new ShareDialogPage(alice.page);
164→
165→    // Initialize page objects for Bob
166→    bobSharedBrowser = new SharedFileBrowserPage(bob.page);
167→    bobContextMenu = new ContextMenuPage(bob.page);
168→
169→    // Initialize page objects for Charlie
170→    charlieSharedBrowser = new SharedFileBrowserPage(charlie.page);
171→
172→    // Verify all three accounts have different public keys
173→    expect(alice.publicKey).not.toBe(bob.publicKey);
174→    expect(alice.publicKey).not.toBe(charlie.publicKey);
175→    expect(bob.publicKey).not.toBe(charlie.publicKey);
176→  });
177→
178→  // ============================================
179→  // Phase 2: Alice Creates Content
180→  // ============================================
181→
182→  test('2.1 Alice creates a test file at root', async () => {
183→    await aliceUploadFile(sharedFileName, sharedFileContent);
184→    expect(await aliceFileList.isItemVisible(sharedFileName)).toBe(true);
185→  });
186→
187→  test('2.2 Alice creates a folder with nested content', async () => {
188→    // Create top-level folder
189→    await aliceCreateFolder(sharedFolderName);
190→    expect(await aliceFileList.isItemVisible(sharedFolderName)).toBe(true);
191→
192→    // Navigate into it and add a file + an image
193→    await aliceNavigateIntoFolder(sharedFolderName);
194→    await aliceUploadFile(folderFile1Name, 'File inside shared folder');
195→
196→    // Upload a PNG image (needed for shared preview test in Phase 11)
197→    const testImage = createTestImageFile(sharedImageName);
198→    await aliceUploadZone.uploadFile(testImage.path);
199→    await aliceFileList.waitForItemToAppear(sharedImageName, { timeout: 30000 });
200→
201→    // Create subfolder
202→    await aliceCreateFolder(subFolderName);
203→
204→    // Navigate into subfolder and add a file
205→    await aliceNavigateIntoFolder(subFolderName);
206→    await aliceUploadFile(folderFile2Name, 'File inside subfolder');
207→
208→    // Navigate back to root
209→    await aliceNavigateBack(); // back to shared folder
210→    await aliceNavigateBack(); // back to root
211→  });
212→
213→  // ============================================
214→  // Phase 3: Basic File Sharing
215→  // ============================================
216→
217→  test('3.1 Alice shares a file with Bob', async () => {
218→    await aliceOpenShareDialog(sharedFileName);
219→
220→    // Should start with no recipients
221→    expect(await aliceShareDialog.getRecipientCount()).toBe(0);
222→
223→    // Share with Bob
224→    await aliceShareDialog.shareWithKey(bob.publicKey);
225→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 30000 });
226→    expect(successText).toContain(truncateKey(bob.publicKey));
227→
228→    // Verify recipient appears in the list
229→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
230→    const recipientKeys = await aliceShareDialog.getRecipientKeys();
231→    expect(recipientKeys[0]).toBe(truncateKey(bob.publicKey));
232→
233→    await aliceShareDialog.close();
