239→    // Wait for the shared items to load
240→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
241→
242→    // Bob should see Alice's shared file
243→    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });
244→    expect(await bobSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
245→
246→    // Verify [RO] badge
247→    const roBadge = bobSharedBrowser.getReadOnlyBadge(sharedFileName);
248→    expect(await roBadge.isVisible()).toBe(true);
249→
250→    // Verify "SHARED BY" shows Alice's truncated key
251→    const sharedBy = await bobSharedBrowser.getSharedBy(sharedFileName);
252→    expect(sharedBy).toContain(truncateKey(alice.publicKey));
